inline MutationValues Priority::into_values() && {
    auto r = memory_resource();
    MutationValues values(r);
    values.fields.emplace(String("id", r), generated_detail::encode(r, id_));
    values.fields.emplace(String("platform_id", r), generated_detail::encode(r, platform_id_));
    values.fields.emplace(String("name", r), generated_detail::encode(r, name_));
    values.fields.emplace(String("code", r), generated_detail::encode(r, code_));
    values.fields.emplace(String("instant", r), generated_detail::encode(r, instant_));
    values.fields.emplace(String("clock", r), generated_detail::encode(r, clock_));
    values.fields.emplace(String("optional_clock", r),
                          generated_detail::encode(r, optional_clock_));
    values.fields.emplace(String("created_at", r), generated_detail::encode(r, created_at_));
    values.fields.emplace(String("updated_at", r), generated_detail::encode(r, updated_at_));
    values.fields.emplace(String("version", r), generated_detail::encode(r, version_));
    detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);
    if (platform_) {
        values.fields.emplace(String("platform", r),
                              Value(r, std::move(*platform_).into_values().fields));
    }
    if (auto relation = std::move(label_list_).into_value()) {
        values.fields.emplace(String("label_list", r), std::move(*relation));
    }
    inject_runtime(values);
    return values;
}

