inline MutationValues Platform::into_values() && {
    auto r = memory_resource();
    MutationValues values(r);
    values.fields.emplace(String("id", r), generated_detail::encode(r, id_));
    values.fields.emplace(String("name", r), generated_detail::encode(r, name_));
    values.fields.emplace(String("created_at", r), generated_detail::encode(r, created_at_));
    values.fields.emplace(String("updated_at", r), generated_detail::encode(r, updated_at_));
    values.fields.emplace(String("version", r), generated_detail::encode(r, version_));
    detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);
    if (auto relation = std::move(priority_list_).into_value()) {
        values.fields.emplace(String("priority_list", r), std::move(*relation));
    }
    if (auto relation = std::move(label_list_).into_value()) {
        values.fields.emplace(String("label_list", r), std::move(*relation));
    }
    inject_runtime(values);
    return values;
}

inline const Platform* Label::platform() const {
    if (platform_) {
        return platform_.get();
    }
    if (!is_loaded("platform")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Platform>(ENTITY_NAME, id(), "platform");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<Platform>(platformId());
}

inline const Priority* Label::priority() const {
    if (priority_) {
        return priority_.get();
    }
    if (!is_loaded("priority")) {
        return nullptr;
    }
    auto* view = root.resolve_relation_option<Priority>(ENTITY_NAME, id(), "priority");
    if (view) {
        return *view ? &**view : nullptr;
    }
    return root.resolve_entity<Priority>(priorityId());
}

inline eval::EvalResult<EntityBorrow<Platform>> Label::evalPlatform() const {
    return GeneratedRelationAccess::object(memory_resource(), "platform", platform(), false);
}

inline eval::EvalResult<EntityBorrow<Priority>> Label::evalPriority() const {
    return GeneratedRelationAccess::object(memory_resource(), "priority", priority(), false);
}

inline std::optional<Json> Label::borrowed_json(Memory r, EntityJsonTraversal& traversal) const {
    GeneratedEntityJson projection(r, traversal, ENTITY_NAME, this, root, id_for_runtime());
    projection.field(
        "id",
        [&] {
            return generated_detail::encode(r, id_);
        },
        load_state.is_loaded("id"),
        true);
    projection.field(
        "platform_id",
        [&] {
            return generated_detail::encode(r, platform_id_);
        },
        load_state.is_loaded("platform_id"),
        false);
    projection.field(
        "priority_id",
        [&] {
            return generated_detail::encode(r, priority_id_);
        },
        load_state.is_loaded("priority_id"),
        false);
    projection.field(
        "code",
        [&] {
            return generated_detail::encode(r, code_);
        },
        load_state.is_loaded("code"),
        false);
    projection.field(
        "version",
        [&] {
            return generated_detail::encode(r, version_);
        },
        load_state.is_loaded("version"),
        true);
    projection.dynamic(dynamic);
    projection.forward<Platform>("platform",
                                 platform_ ? &*platform_ : nullptr,
                                 load_state.is_loaded("platform"),
                                 generated_detail::encode(r, platform_id_));
    projection.forward<Priority>("priority",
                                 priority_ ? &*priority_ : nullptr,
                                 load_state.is_loaded("priority"),
                                 generated_detail::encode(r, priority_id_));
    return projection.finish(dynamic_field_values());
}

inline void Label::attachRuntimeStateRecursive(const EntityRuntimeState& target) {
    root.attach_runtime_state(target);
    if (platform_) {
        platform_->attachRuntimeStateRecursive(target);
    }
    if (priority_) {
        priority_->attachRuntimeStateRecursive(target);
    }
}

inline Label::Label(std::allocator_arg_t, Allocator a)
    : Base(std::allocator_arg, a),
      id_(generated_detail::default_value<std::uint64_t>(a.resource())),
      platform_id_(generated_detail::default_value<std::uint64_t>(a.resource())),
      priority_id_(generated_detail::default_value<std::uint64_t>(a.resource())),
      code_(generated_detail::default_value<String>(a.resource())),
      version_(generated_detail::default_value<std::int64_t>(a.resource())),
      platform_(nullptr, detail::ScopedDelete<Platform>{a.resource()}),
      priority_(nullptr, detail::ScopedDelete<Priority>{a.resource()}) {}

inline Label::Label(std::allocator_arg_t, Allocator a, const Label& other)
    : Base(std::allocator_arg, a, other), id_(detail::clone_in(a.resource(), other.id_)),
      platform_id_(detail::clone_in(a.resource(), other.platform_id_)),
      priority_id_(detail::clone_in(a.resource(), other.priority_id_)),
      code_(detail::clone_in(a.resource(), other.code_)),
      version_(detail::clone_in(a.resource(), other.version_)),
      platform_(generated_detail::copy_box(a.resource(), other.platform_)),
      priority_(generated_detail::copy_box(a.resource(), other.priority_)) {}

inline Label::Label(Label&&) noexcept = default;
inline Label::~Label() = default;

inline EntityDescriptor Label::entity_descriptor(Memory r) {
    EntityDescriptor d(std::allocator_arg, Allocator(r), ENTITY_NAME);
    d.table("label_data");
    d.service("sqlite");
    {
        auto& property = d.property("id", DataType::U64, "id").id().not_null();
        (void)property;
    }
    {
        auto& property = d.property("code", DataType::Text, "code").not_null();
        property.with_max_length(100);
        (void)property;
    }
    {
        auto& property = d.property("version", DataType::I64, "version").version().not_null();
        (void)property;
    }
    {
        auto& property = d.property("platform_id", DataType::U64, "platform").not_null();
        (void)property;
    }
    {
        auto& property = d.property("priority_id", DataType::U64, "priority").not_null();
        (void)property;
    }
    {
        auto& relation = d.relation("platform", "Platform");
        relation.local_key = "platform_id";
        relation.foreign_key = "id";
        relation.many = false;
    }
    {
        auto& relation = d.relation("priority", "Priority");
        relation.local_key = "priority_id";
        relation.foreign_key = "id";
        relation.many = false;
    }
    d.mask_fields({});
    return d;
}

inline Result<Label, EntityError> Label::from_compact_row(Memory r, CompactRow row) {
    using Outcome = Result<Label, EntityError>;
    Label result(std::allocator_arg, Allocator(r));
    auto captured =
        detail::EntityRuntimeAccess::capture_dynamic_values(result.dynamic, row, field_layout(r));
    if (!captured) {
        return Outcome::err(r, std::move(captured).error());
    }
    ArenaBorrow<FieldLayout> field_layout_binding(
        std::allocator_arg, Allocator(r), field_layout(r));
    auto id_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "id", "id", false, field_layout_binding);
    if (!id_lookup) {
        return Outcome::err(r, std::move(id_lookup).error());
    }
    auto platform_id_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "platform_id", "platform", true, field_layout_binding);
    if (!platform_id_lookup) {
        return Outcome::err(r, std::move(platform_id_lookup).error());
    }
    auto priority_id_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "priority_id", "priority", true, field_layout_binding);
    if (!priority_id_lookup) {
        return Outcome::err(r, std::move(priority_id_lookup).error());
    }
    auto code_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "code", "code", false, field_layout_binding);
    if (!code_lookup) {
        return Outcome::err(r, std::move(code_lookup).error());
    }
    auto version_lookup = GeneratedRelationAccess::lookupField(
        r, row, ENTITY_NAME, "version", "version", false, field_layout_binding);
    if (!version_lookup) {
        return Outcome::err(r, std::move(version_lookup).error());
    }
    auto id_value =
        generated_detail::decode<std::uint64_t>(r, id_lookup.value().value, ENTITY_NAME, "id");
    if (!id_value) {
        return Outcome::err(r, std::move(id_value).error());
    }
    result.id_ = std::move(id_value).value();
    auto platform_id_value = generated_detail::decode<std::uint64_t>(
        r, platform_id_lookup.value().value, ENTITY_NAME, "platform_id");
    if (!platform_id_value) {
        return Outcome::err(r, std::move(platform_id_value).error());
    }
    result.platform_id_ = std::move(platform_id_value).value();
    auto priority_id_value = generated_detail::decode<std::uint64_t>(
        r, priority_id_lookup.value().value, ENTITY_NAME, "priority_id");
    if (!priority_id_value) {
        return Outcome::err(r, std::move(priority_id_value).error());
    }
    result.priority_id_ = std::move(priority_id_value).value();
    auto code_value =
        generated_detail::decode<String>(r, code_lookup.value().value, ENTITY_NAME, "code");
    if (!code_value) {
        return Outcome::err(r, std::move(code_value).error());
    }
    result.code_ = std::move(code_value).value();
    auto version_value = generated_detail::decode<std::int64_t>(
        r, version_lookup.value().value, ENTITY_NAME, "version");
    if (!version_value) {
        return Outcome::err(r, std::move(version_value).error());
    }
    result.version_ = std::move(version_value).value();
    auto platform_decoded = GeneratedRelationAccess::decodeObject<Platform>(r, row.get("platform"));
    if (!platform_decoded) {
        return Outcome::err(r, std::move(platform_decoded).error());
    }
    if (platform_decoded.value()) {
        result.platform_ = detail::make_box<Platform>(r, std::move(*platform_decoded.value()));
    }
    auto priority_decoded = GeneratedRelationAccess::decodeObject<Priority>(r, row.get("priority"));
    if (!priority_decoded) {
        return Outcome::err(r, std::move(priority_decoded).error());
    }
    if (priority_decoded.value()) {
        result.priority_ = detail::make_box<Priority>(r, std::move(*priority_decoded.value()));
    }
    result.load_state = row.indexed_load_state(
        detail::ContextArena::from_memory(r).loaded_snapshots(), field_layout(r));
    if (platform_id_lookup.value().alias_present) {
        auto& pool = detail::ContextArena::from_memory(r).loaded_snapshots();
        if (!platform_id_lookup.value().object_alias && !row.is_loaded_relation("platform")) {
            result.load_state.mark_unloaded("platform", &pool).value();
        }
        result.load_state.mark_loaded("platform_id", &pool).value();
    }
    if (priority_id_lookup.value().alias_present) {
        auto& pool = detail::ContextArena::from_memory(r).loaded_snapshots();
        if (!priority_id_lookup.value().object_alias && !row.is_loaded_relation("priority")) {
            result.load_state.mark_unloaded("priority", &pool).value();
        }
        result.load_state.mark_loaded("priority_id", &pool).value();
    }
    result.root.set_original_compact_row(ENTITY_NAME, row);
    return Outcome::ok(r, std::move(result));
}

inline MutationValues Label::into_values() && {
    auto r = memory_resource();
    MutationValues values(r);
    values.fields.emplace(String("id", r), generated_detail::encode(r, id_));
    values.fields.emplace(String("platform_id", r), generated_detail::encode(r, platform_id_));
    values.fields.emplace(String("priority_id", r), generated_detail::encode(r, priority_id_));
    values.fields.emplace(String("code", r), generated_detail::encode(r, code_));
    values.fields.emplace(String("version", r), generated_detail::encode(r, version_));
    detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);
    if (platform_) {
        values.fields.emplace(String("platform", r),
                              Value(r, std::move(*platform_).into_values().fields));
    }
    if (priority_) {
        values.fields.emplace(String("priority", r),
                              Value(r, std::move(*priority_).into_values().fields));
    }
    inject_runtime(values);
    return values;
}

inline Label& Label::updatePlatform(const Platform& value) {
    platform_ = detail::make_box<Platform>(memory_resource(), value);
    updatePlatformId(value.id());
    return *this;
}

inline Label& Label::updatePriority(const Priority& value) {
    priority_ = detail::make_box<Priority>(memory_resource(), value);
    updatePriorityId(value.id());
    return *this;
}
